                assert_eq!(
                    said.trim(),
                    "branch:root:root+branch7/a 7/1 \
                     root+branch/t/branch:root:root+branch7/a | \
                     root+branch/t/branch:root:root+branch7/a!7 \
                     root+branch/root+branch/1 1 root/p/root:root1 7 2"
                );
